const explanations=[
[/airport/i,{simple:"This research follows the agreements and public decisions governing Pueblo Memorial Airport. The airport involves municipal operations, leases, aviation obligations and public funds that cannot be treated as one agreement.",why:"Lease terms, airport business activity and restricted grant funds can affect tenants, residents, taxpayers and future service."}],
[/pura|rta|urban renewal|tif/i,{simple:"This case is part of Pueblo's urban-renewal and public-finance system. The City and urban-renewal authority can be connected through projects, loans or reimbursements while retaining distinct legal and accounting obligations.",why:"A loan, tax increment, repayment schedule and completed public benefit are different financial objects. Each needs its own record."}],
[/half.cent|economic development|incentive|tortuga|puebloplex/i,{simple:"This case concerns economic-development decisions and how publicly supported projects move from proposal to agreement, spending and measurable results.",why:"Residents need to know which public resources are committed, what is legally promised, and which jobs, assets or revenues actually materialize."}],
[/pueblo west|desert hawk/i,{simple:"This research focuses on Pueblo West's public-service and financial arrangements, including responsibilities that may cross district, county or enterprise boundaries.",why:"Residents experience service quality, utility rates and taxes directly, while the underlying authority and funding may be divided among institutions."}],
[/black hills|energy|utility proceedings/i,{simple:"This case tracks utility or energy decisions through proposals, regulatory review, final orders and their effects on customers and local infrastructure.",why:"A proposed rate or resource plan is not the same as an approved change, a final bill or a proven economic impact."}],
[/aspen acres|post.fire|wildfire|watershed/i,{simple:"This research follows Pueblo-area disaster recovery from the incident through housing, infrastructure, environmental risks and long-term rebuilding obligations.",why:"Insurance payments, government aid, repairs and household recovery often follow different rules and schedules."}],
[/steel|mission foods|industrial/i,{simple:"This case examines employment and industrial transition in Pueblo: companies, workers, facilities, supporting infrastructure and public investment.",why:"Projected or announced employment is different from realized jobs, wages, worker transitions and tax receipts."}],
[/ballot|2026 2a|campaign|election/i,{simple:"This entry follows the legal and financial effects of an election-related issue. The certified text and official results govern what actually changes.",why:"Campaign claims, election-night counts, approved measures and implemented policies are separate sources and stages."}],
[/school|education/i,{simple:"This research examines public education governance, finance, facilities or services across the region's school districts and institutions.",why:"School-board responsibilities, bond obligations, pupil needs and outcomes can extend beyond one governing agency."}],
[/rural health|homelessness|health|pdphe/i,{simple:"This entry examines regional health or human services, including how institutions, public programs, providers and funding arrangements connect.",why:"A funded program must be evaluated through actual access, service quality and outcomes without exposing private client records."}],
[/water|arkansas valley conduit|wastewater/i,{simple:"This issue concerns Pueblo-region water or wastewater infrastructure and how service areas, legal authority, capital requirements and shared resources connect.",why:"Water reliability depends on rights, storage, treatment, maintenance and long-term costs rather than a single project announcement."}],
[/speed enforcement|dfr|surveillance|technology|e.911/i,{simple:"This case follows public technology or safety systems from legal authorization and procurement through actual deployment and oversight.",why:"Vendor claims or available technical capabilities do not establish effectiveness, legal compliance or equitable outcomes."}],
[/county|capital|grant|debt|budget|finance/i,{simple:"This financial research traces how a Pueblo-region public decision is authorized, financed, implemented and accounted for.",why:"Government commitments, legal obligations, payments, reimbursements and service results belong in separate ledgers."}]
];
function description(x){let found=explanations.find(p=>p[0].test(x.t+" "+x.d));return found?found[1]:{simple:"This archived research entry identifies a Pueblo-region public issue and the institutions and records that need to be connected to understand it. It is an entry in the evidence system, not a finding of misconduct or completed project.",why:"Regional decisions can span government, employers, utilities, residents and other institutions. The responsible authority, money and measured outcome must be distinguished."};}
function related(x){
 const firstIds=new Set(x.e), direct=ITEMS.filter(y=>y.id!==x.id&&y.e.some(id=>firstIds.has(id))).slice(0,12);
 const used=new Set([x.id,...direct.map(y=>y.id)]), nextIds=new Set(direct.flatMap(y=>y.e));
 const second=ITEMS.filter(y=>!used.has(y.id)&&y.e.some(id=>nextIds.has(id))).slice(0,10);
 second.forEach(y=>used.add(y.id));
 const thirdIds=new Set(second.flatMap(y=>y.e));
 const third=ITEMS.filter(y=>!used.has(y.id)&&y.e.some(id=>thirdIds.has(id))).slice(0,8);
 return [direct,second,third];
}
